CREATE TABLE IF NOT EXISTS users (id varchar(64) PRIMARY KEY, open_id varchar(191) NOT NULL, name varchar(191) NOT NULL, email varchar(191), created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY users_open_id_idx (open_id));
CREATE TABLE IF NOT EXISTS workspaces (id varchar(64) PRIMARY KEY, name varchar(191) NOT NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workspace_members (id varchar(64) PRIMARY KEY, workspace_id varchar(64) NOT NULL, user_id varchar(64) NOT NULL, role varchar(32) NOT NULL DEFAULT 'member', created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY workspace_members_unique_idx (workspace_id, user_id), KEY workspace_members_workspace_idx (workspace_id));
CREATE TABLE IF NOT EXISTS connected_accounts (id varchar(64) PRIMARY KEY, workspace_id varchar(64) NOT NULL, username varchar(191) NOT NULL, display_name varchar(191) NOT NULL, status varchar(32) NOT NULL, encrypted_credential_ref varchar(255), token_expires_at timestamp NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY connected_accounts_workspace_idx (workspace_id));
CREATE TABLE IF NOT EXISTS campaigns (id varchar(64) PRIMARY KEY, workspace_id varchar(64) NOT NULL, account_id varchar(64) NOT NULL, external_id varchar(191), name varchar(191) NOT NULL, objective varchar(80) NOT NULL, status varchar(32) NOT NULL, budget_cents int, synced_at timestamp NULL, KEY campaigns_account_idx (account_id));
CREATE TABLE IF NOT EXISTS comments (id varchar(64) PRIMARY KEY, workspace_id varchar(64) NOT NULL, account_id varchar(64) NOT NULL, external_id varchar(191) NOT NULL, username varchar(191) NOT NULL, body text NOT NULL, post_external_id varchar(191), reply_status varchar(32) NOT NULL DEFAULT 'needs_reply', created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY comments_external_idx (account_id, external_id), KEY comments_inbox_idx (workspace_id, reply_status, created_at));
CREATE TABLE IF NOT EXISTS ai_reply_drafts (id varchar(64) PRIMARY KEY, workspace_id varchar(64) NOT NULL, comment_id varchar(64) NOT NULL, tone varchar(80) NOT NULL, body text NOT NULL, confidence int, approved_at timestamp NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS automation_rules (id varchar(64) PRIMARY KEY, workspace_id varchar(64) NOT NULL, account_id varchar(64) NOT NULL, name varchar(191) NOT NULL, mode varchar(32) NOT NULL DEFAULT 'approval', active boolean NOT NULL DEFAULT true, config_json text, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id varchar(64) PRIMARY KEY, workspace_id varchar(64) NOT NULL, actor_user_id varchar(64), action varchar(100) NOT NULL, target_type varchar(80) NOT NULL, target_id varchar(64), metadata_json text, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
